import {fresh,element} from './model.js';
import {options} from './editor-core.js';

const put=(type,props,custom)=>{const e=element(type);Object.assign(e,props);if(custom)e.custom=custom;return e;};
const child=(type,parent,x,y,width,height,props={})=>put(type,{parentId:parent.id,x,y,width,height,...props});

function neon(){const p=fresh();p.name='Neon Orbit';p.canvas={width:1920,height:1080,background:'#070816',desktop:{mode:'gradient',gradientEnd:'#17103a',angle:135,image:'',fit:'cover',position:'center',showText:false,text:'',textColor:'#8be9fd'}};p.hyprland={...p.hyprland,gapsIn:8,gapsOut:18,rounding:18,activeBorder:'#c77dff',inactiveBorder:'#24243e',blurSize:12,blurPasses:3};const bar=put('bar',{name:'Neon top bar',x:40,y:28,width:1840,height:60,fill:'#11142b',color:'#e0d7ff',radius:20});bar.appearance={opacity:.72,blur:18,shadow:26,borderWidth:1,borderColor:'#6c63ff',font:'sans-serif',fontAsset:''};const ws=child('workspaces',bar,18,10,260,40),clock=child('clock',bar,790,8,260,44,{fontSize:22}),network=child('network',bar,1510,10,135,40),battery=child('battery',bar,1655,10,145,40);const hero=put('widget',{name:'Neon greeting',x:120,y:230,width:620,height:260,fill:'#11142b',color:'#c77dff',fontSize:52,radius:32},{text:'NIGHT MODE\n{{time}}',dataSource:'time',shape:'rectangle'});hero.appearance={opacity:.68,blur:22,shadow:40,borderWidth:2,borderColor:'#6c63ff',font:'sans-serif',fontAsset:''};hero.animation={...hero.animation,kind:'slide',iteration:'once',duration:900};const orbit=put('shape',{name:'Neon orbit',x:1410,y:300,width:230,height:230,fill:'#6c63ff',color:'#070816',fontSize:64,radius:115},{text:'✦',dataSource:'static',shape:'circle'});orbit.animation={...orbit.animation,kind:'glow',duration:1800};const dock=put('dock',{name:'Neon dock',x:610,y:955,width:700,height:86,fill:'#11142b',color:'#e0d7ff',radius:28});dock.options={...options(dock),align:'center',gap:30,items:[['terminal','⌘','Terminal'],['browser','◎','Browser'],['files','▣','Files'],['music','♫','Music'],['settings','⚙','Settings']].map(([actionId,icon,label])=>({id:crypto.randomUUID(),actionId,icon,label,action:'',shortcut:''}))};dock.appearance={opacity:.76,blur:20,shadow:35,borderWidth:1,borderColor:'#c77dff',font:'sans-serif',fontAsset:''};p.elements=[bar,ws,clock,network,battery,hero,orbit,dock];return p;}

function paper(){const p=fresh();p.name='Paper Calm';p.canvas={width:1440,height:900,background:'#eee9df',desktop:{mode:'solid',gradientEnd:'#d7cfc0',angle:0,image:'',fit:'cover',position:'center',showText:false,text:'',textColor:'#34312d'}};p.hyprland={...p.hyprland,gapsIn:12,gapsOut:22,borderSize:1,rounding:8,activeBorder:'#8b5e3c',inactiveBorder:'#c8bfae',blurEnabled:false,shadowRange:8,activeOpacity:1,inactiveOpacity:.97,animationStyle:'fade'};const title=put('text',{name:'Editorial date',x:100,y:150,width:820,height:160,fill:'#eee9df',color:'#3e3a34',fontSize:54},{text:'{{value}}',dataSource:'date',shape:'rectangle'});title.appearance={opacity:0,blur:0,shadow:0,borderWidth:0,borderColor:'#8b5e3c',font:'serif',fontAsset:''};const line=put('shape',{name:'Rule',x:100,y:330,width:680,height:4,fill:'#8b5e3c',color:'#8b5e3c',radius:2},{text:'',dataSource:'static',shape:'rectangle'});const note=put('text',{name:'Daily note',x:100,y:365,width:640,height:120,fill:'#eee9df',color:'#6f665b',fontSize:22},{text:'Make room for quiet work.\nOne window at a time.',dataSource:'static',shape:'rectangle'});note.appearance={opacity:0,blur:0,shadow:0,borderWidth:0,borderColor:'#8b5e3c',font:'serif',fontAsset:''};const bar=put('bar',{name:'Paper rail',x:1040,y:90,width:300,height:720,fill:'#e2dbcf',color:'#3e3a34',radius:16});bar.options={...options(bar),orientation:'vertical',align:'start',padding:24,gap:20};const clock=child('clock',bar,25,30,250,90,{fontSize:34,fill:'#e2dbcf',color:'#8b5e3c'}),ws=child('workspaces',bar,25,145,250,48,{fill:'#e2dbcf',color:'#3e3a34'}),cpu=child('cpu',bar,25,235,250,54,{fill:'#d7cfc0',color:'#3e3a34'}),memory=child('memory',bar,25,305,250,54,{fill:'#d7cfc0',color:'#3e3a34'}),battery=child('battery',bar,25,375,250,54,{fill:'#d7cfc0',color:'#3e3a34'}),power=child('power',bar,25,610,250,54,{fill:'#8b5e3c',color:'#fffaf0'});p.elements=[title,line,note,bar,clock,ws,cpu,memory,battery,power];return p;}

function paperEdge(){const p=paper();p.name='Paper Calm Edge';const rail=p.elements.find(e=>e.name==='Paper rail');Object.assign(rail,{name:'Paper edge rail',x:18,y:90,width:300,height:720,anchorX:'left',anchorY:'center'});rail.reveal={mode:'hot-edge',edge:'left',triggerSize:5,hideDelay:420};rail.appearance={opacity:.96,blur:10,shadow:26,borderWidth:1,borderColor:'#c8bfae',font:'serif',fontAsset:''};for(const e of p.elements.filter(e=>e.parentId===rail.id))e.reveal={mode:'always',edge:'left',triggerSize:4,hideDelay:350};const title=p.elements.find(e=>e.name==='Editorial date'),line=p.elements.find(e=>e.name==='Rule'),note=p.elements.find(e=>e.name==='Daily note');title.x=430;line.x=430;note.x=430;title.workspaceContent=['{{value}}','TODAY’S TASKS','IDEAS IN MOTION','WEEKLY RESET','QUIET REVIEW'];title.workspaceMotion={order:0};line.workspaceContent=['','','','',''];line.workspaceMotion={order:1};note.workspaceContent=['Make room for quiet work.\nOne window at a time.','01  Review the inbox\n02  Draft the project outline\n03  Take a 20-minute focus sprint\n04  Plan tomorrow’s first step','Capture one useful thought.\nLeave the rest for later.','Clear the desk.\nChoose the next three priorities.','Notice what worked.\nAdjust one thing for tomorrow.'];note.workspaceMotion={order:2};p.integrations={...p.integrations,shell:'quickshell'};return p;}

function aurora(){const p=fresh();p.name='Aurora Grid';p.canvas={width:1600,height:1000,background:'#071713',desktop:{mode:'gradient',gradientEnd:'#102d27',angle:160,image:'',fit:'cover',position:'center',showText:false,text:'',textColor:'#b8f2e6'}};p.hyprland={...p.hyprland,gapsIn:5,gapsOut:10,rounding:24,activeBorder:'#64ffda',inactiveBorder:'#183d35',blurSize:16,blurPasses:3,layout:'master'};const top=put('bar',{name:'Aurora status',x:30,y:28,width:1540,height:64,fill:'#0b2821',color:'#d8fff5',radius:22});top.appearance={opacity:.78,blur:16,shadow:22,borderWidth:1,borderColor:'#2f7f6d',font:'sans-serif',fontAsset:''};const ws=child('workspaces',top,18,12,270,40),music=child('music',top,570,12,350,40,{fill:'#0b2821',color:'#64ffda'}),clock=child('clock',top,1290,10,220,44,{fontSize:24,fill:'#0b2821',color:'#d8fff5'});const monitor=put('widget',{name:'Aurora metrics',x:100,y:190,width:520,height:300,fill:'#0b2821',color:'#64ffda',fontSize:24,radius:30},{text:'SYSTEM GRID',dataSource:'static',shape:'rectangle'});monitor.appearance={opacity:.72,blur:20,shadow:35,borderWidth:1,borderColor:'#2f7f6d',font:'monospace',fontAsset:''};const cpu=child('text',monitor,30,85,210,78,{name:'CPU card',fill:'#123f35',color:'#b8f2e6',fontSize:20,radius:18});cpu.custom={text:'CPU  {{value}}',dataSource:'cpu',shape:'rectangle'};const mem=child('text',monitor,270,85,210,78,{name:'Memory card',fill:'#123f35',color:'#b8f2e6',fontSize:20,radius:18});mem.custom={text:'RAM  {{value}}',dataSource:'memory',shape:'rectangle'};const bat=child('text',monitor,30,185,450,78,{name:'Battery card',fill:'#64ffda',color:'#071713',fontSize:20,radius:18});bat.custom={text:'POWER  {{value}}',dataSource:'battery',shape:'pill'};const date=put('text',{name:'Aurora date',x:900,y:260,width:560,height:150,fill:'#071713',color:'#b8f2e6',fontSize:44},{text:'{{value}}',dataSource:'date',shape:'rectangle'});date.appearance={opacity:0,blur:0,shadow:0,borderWidth:0,borderColor:'#64ffda',font:'sans-serif',fontAsset:''};date.animation={...date.animation,kind:'float',duration:3200};const dock=put('dock',{name:'Aurora dock',x:470,y:870,width:660,height:88,fill:'#0b2821',color:'#d8fff5',radius:30});dock.options={...options(dock),align:'center',gap:28,items:[['terminal','⌘','Code'],['browser','◎','Web'],['files','▣','Files'],['music','♫','Audio'],['lock','◇','Lock']].map(([actionId,icon,label])=>({id:crypto.randomUUID(),actionId,icon,label,action:'',shortcut:''}))};p.elements=[top,ws,music,clock,monitor,cpu,mem,bat,date,dock];return p;}

export const DESKTOP_PRESETS=[{name:'Neon Orbit',description:'Purple neon, floating glass and a centered dock',create:neon},{name:'Paper Calm',description:'Warm editorial layout with a vertical rail',create:paper},{name:'Paper Calm Edge',description:'Paper Calm with a left hot-edge overlay above applications',create:paperEdge},{name:'Aurora Grid',description:'Green glass system dashboard and dock',create:aurora}];
